import{_ as l,C as h,o as a,c as u,a2 as c,b as n,w as o,a as d,E as s,a3 as i,j as t}from"./chunks/framework.CZqXuAiL.js";const _=JSON.parse('{"title":"Architecture Overview","description":"How Bandwidth Monitor is built — the two-half panel + node design, pairing sequence, data flow from veth counters to panel charts, database schemas on both sides, the 48-hour aggregation boundary, and the concurrency model.","frontmatter":{"title":"Architecture Overview","description":"How Bandwidth Monitor is built — the two-half panel + node design, pairing sequence, data flow from veth counters to panel charts, database schemas on both sides, the 48-hour aggregation boundary, and the concurrency model."},"headers":[],"relativePath":"pterodactyl-bandwidth-monitor/architecture/overview.md","filePath":"pterodactyl-bandwidth-monitor/architecture/overview.md","lastUpdated":null}'),p={name:"pterodactyl-bandwidth-monitor/architecture/overview.md"};function b(g,e,m,v,y,w){const r=h("Mermaid");return a(),u("div",null,[e[3]||(e[3]=c('<h1 id="architecture-overview" tabindex="-1">Architecture Overview <a class="header-anchor" href="#architecture-overview" aria-label="Permalink to &quot;Architecture Overview&quot;">​</a></h1><p>Bandwidth Monitor is two cooperating halves with a strict wire contract between them:</p><ul><li><strong>Panel addon</strong> (<code>pterodactylbandwidth</code>) — a Blueprint extension inside the Pterodactyl panel (PHP/Laravel). Owns the admin UI, pairing tokens, per-server limits, usage rollups, reports, predictions, and settings. State lives in the panel&#39;s MySQL database in eight <code>bandwidth_*</code> tables.</li><li><strong>Node agent</strong> (<code>bandwidth-noded</code>) — a Go daemon on every Wings node. Discovers server containers, counts bytes on their veth interfaces, enforces speed caps and quotas with <code>tc</code>, and syncs with the panel. State lives in a local SQLite database.</li></ul><p>The halves never share a database. Everything crosses the wire through the documented <a href="./../user-guide/api">API contract</a>: the node calls the panel (register, heartbeat, limits pull, events, suspend), and the panel calls the node (stats, history, limits push, unthrottle).</p><hr><h2 id="component-diagram" tabindex="-1">Component diagram <a class="header-anchor" href="#component-diagram" aria-label="Permalink to &quot;Component diagram&quot;">​</a></h2>',6)),(a(),n(i,null,{default:o(()=>[s(r,{id:"mermaid-25",class:"mermaid",graph:"flowchart%20LR%0A%20%20%20%20subgraph%20Panel%5B%22Pterodactyl%20Panel%20(PHP%20%2F%20Laravel)%22%5D%0A%20%20%20%20%20%20%20%20direction%20TB%0A%20%20%20%20%20%20%20%20UI%5B%22Admin%20UI%3Cbr%2F%3EDashboard%20%C2%B7%20Nodes%20%C2%B7%20Servers%3Cbr%2F%3EReports%20%C2%B7%20Settings%20%C2%B7%20Events%22%5D%0A%20%20%20%20%20%20%20%20CTRL%5B%22Admin%20Controllers%22%5D%0A%20%20%20%20%20%20%20%20APIP%5B%22Node-facing%20API%3Cbr%2F%3E%2Fapi%2Fbandwidth%2Fnode%22%5D%0A%20%20%20%20%20%20%20%20SVC%5B%22Services%3Cbr%2F%3Elimits%20%C2%B7%20tokens%20%C2%B7%20settings%3Cbr%2F%3Eusage%20query%20%C2%B7%20predictions%3Cbr%2F%3Enode%20HTTP%20client%22%5D%0A%20%20%20%20%20%20%20%20JOBS%5B%22Queued%20Jobs%3Cbr%2F%3Epoll%20%C2%B7%20aggregate%20%C2%B7%20prune%20%C2%B7%20push-limits%22%5D%0A%20%20%20%20%20%20%20%20MYSQL%5B(%22MySQL%3Cbr%2F%3Ebandwidth_*%20tables%22)%5D%0A%20%20%20%20%20%20%20%20UI%20--%3E%20CTRL%20--%3E%20SVC%0A%20%20%20%20%20%20%20%20APIP%20--%3E%20SVC%0A%20%20%20%20%20%20%20%20JOBS%20--%3E%20SVC%0A%20%20%20%20%20%20%20%20SVC%20--%3E%20MYSQL%0A%20%20%20%20%20%20%20%20JOBS%20--%3E%20MYSQL%0A%20%20%20%20end%0A%0A%20%20%20%20subgraph%20Node%5B%22Wings%20Node%20(Go%20agent)%22%5D%0A%20%20%20%20%20%20%20%20direction%20TB%0A%20%20%20%20%20%20%20%20DISC%5B%22discovery%3Cbr%2F%3Econtainer%20%E2%86%94%20UUID%20%E2%86%94%20veth%22%5D%0A%20%20%20%20%20%20%20%20MON%5B%22monitor%3Cbr%2F%3E%2Fsys%20veth%20counters%22%5D%0A%20%20%20%20%20%20%20%20QUOTA%5B%22quota%3Cbr%2F%3Ecalendar%20periods%22%5D%0A%20%20%20%20%20%20%20%20TC%5B%22tc%20manager%3Cbr%2F%3EHTB%20%2B%20ingress%20police%22%5D%0A%20%20%20%20%20%20%20%20PANELC%5B%22panel%20client%3Cbr%2F%3Eregister%20%C2%B7%20heartbeat%20%C2%B7%20events%22%5D%0A%20%20%20%20%20%20%20%20APIN%5B%22node%20API%20%3A8480%3Cbr%2F%3Estats%20%C2%B7%20limits%20%C2%B7%20unthrottle%22%5D%0A%20%20%20%20%20%20%20%20SQLITE%5B(%22SQLite%3Cbr%2F%3Ebandwidth-node.db%22)%5D%0A%20%20%20%20%20%20%20%20DISC%20--%3E%20MON%20--%3E%20QUOTA%20--%3E%20TC%0A%20%20%20%20%20%20%20%20PANELC%20--%3E%20SQLITE%0A%20%20%20%20%20%20%20%20MON%20--%3E%20SQLITE%0A%20%20%20%20%20%20%20%20QUOTA%20--%3E%20SQLITE%0A%20%20%20%20end%0A%0A%20%20%20%20SVC%20--%3E%7C%22GET%20%2Fstats%20%C2%B7%20PUT%20%2Flimits%3Cbr%2F%3EPOST%20%2Funthrottle%22%7C%20APIN%0A%20%20%20%20PANELC%20--%3E%7C%22register%20%C2%B7%20heartbeat%3Cbr%2F%3EGET%20%2Flimits%20%C2%B7%20events%20%C2%B7%20suspend%22%7C%20APIP%0A%20%20%20%20TC%20-.-%3E%7C%22shapes%22%7C%20VETH%5B%22container%20veths%22%5D%0A%20%20%20%20MON%20-.-%3E%7C%22reads%22%7C%20VETH%0A"})]),fallback:o(()=>[...e[0]||(e[0]=[d(" Loading... ",-1)])]),_:1})),e[4]||(e[4]=t("hr",null,null,-1)),e[5]||(e[5]=t("h2",{id:"pairing-sequence",tabindex:"-1"},[d("Pairing sequence "),t("a",{class:"header-anchor",href:"#pairing-sequence","aria-label":'Permalink to "Pairing sequence"'},"​")],-1)),(a(),n(i,null,{default:o(()=>[s(r,{id:"mermaid-30",class:"mermaid",graph:"sequenceDiagram%0A%20%20%20%20autonumber%0A%20%20%20%20participant%20A%20as%20Admin%0A%20%20%20%20participant%20P%20as%20Panel%0A%20%20%20%20participant%20N%20as%20Node%20agent%0A%0A%20%20%20%20A-%3E%3EP%3A%20Open%20Bandwidth%20%E2%86%92%20Nodes%0A%20%20%20%20P-%3E%3EP%3A%20Generate%2064-hex%20token%20per%20node%3Cbr%2F%3E(bcrypt%20hash%20%2B%20encrypted%20copy%20%2B%2016-char%20prefix)%0A%20%20%20%20A-%3E%3EP%3A%20View%20Token%0A%20%20%20%20A-%3E%3EN%3A%20Run%20install.sh%20as%20root%3Cbr%2F%3E(panel%20URL%20%2B%20token%20%2B%20listen%20addr%2Fport)%0A%20%20%20%20N-%3E%3EN%3A%20Write%20%2Fetc%2Fbandwidth-node%2F%7Bconfig.yaml%2Ctoken%7D%3Cbr%2F%3Einstall%20%2B%20start%20systemd%20unit%0A%20%20%20%20loop%20Until%20success%20(backoff%201s%20%E2%86%92%2030s)%0A%20%20%20%20%20%20%20%20N-%3E%3EP%3A%20POST%20%2Fapi%2Fbandwidth%2Fnode%2Fregister%0A%20%20%20%20end%0A%20%20%20%20P-%3E%3EP%3A%20Verify%20bearer%20(prefix%20lookup%20%2B%20bcrypt)%3Cbr%2F%3Erecord%20api_url%2C%20mark%20online%0A%20%20%20%20P--%3E%3EN%3A%20node_id%2C%20heartbeat_interval%2C%20config_version%0A%20%20%20%20N-%3E%3EP%3A%20GET%20%2Fapi%2Fbandwidth%2Fnode%2Flimits%0A%20%20%20%20N-%3E%3EN%3A%20Persist%20limits%2C%20apply%20tc%20rules%0A%20%20%20%20loop%20Every%20heartbeat%20interval%20(default%2060s)%0A%20%20%20%20%20%20%20%20N-%3E%3EP%3A%20POST%20%2Fheartbeat%20(aggregate%20stats)%0A%20%20%20%20%20%20%20%20P--%3E%3EN%3A%20config_version%0A%20%20%20%20%20%20%20%20Note%20over%20N%3A%20version%20drift%20%E2%86%92%20pull%20GET%20%2Flimits%0A%20%20%20%20end%0A"})]),fallback:o(()=>[...e[1]||(e[1]=[d(" Loading... ",-1)])]),_:1})),e[6]||(e[6]=t("p",null,"If a heartbeat gets a 401 (e.g. after a panel-side token reset) or fails 5 times in a row, the agent re-runs registration instead of dead-ending until restart.",-1)),e[7]||(e[7]=t("hr",null,null,-1)),e[8]||(e[8]=t("h2",{id:"data-flow-veth-counters-to-charts",tabindex:"-1"},[d("Data flow: veth counters to charts "),t("a",{class:"header-anchor",href:"#data-flow-veth-counters-to-charts","aria-label":'Permalink to "Data flow: veth counters to charts"'},"​")],-1)),(a(),n(i,null,{default:o(()=>[s(r,{id:"mermaid-38",class:"mermaid",graph:"flowchart%20TD%0A%20%20%20%20VETH%5B%22%2Fsys%2Fclass%2Fnet%2Fveth*%2Fstatistics%3Cbr%2F%3E(rx_bytes%20%2F%20tx_bytes)%22%5D%20--%3E%7C%225s%20poll%2C%20deltas%22%7C%20AGDB%5B(%22Node%20SQLite%3Cbr%2F%3Eservers%20%2B%20usage_hourly%22)%5D%0A%20%20%20%20AGDB%20--%3E%7C%22GET%20%2Fapi%2Fv1%2Fstats%20(cumulative%20counters)%22%7C%20POLL%5B%22Panel%20poll%20job%3Cbr%2F%3E(every%20minute%2C%20per%20online%20node)%22%5D%0A%20%20%20%20POLL%20--%3E%7C%22deltas%20vs%20bandwidth_server_state%22%7C%20HOUR%5B(%22bandwidth_usage_hourly%3Cbr%2F%3EMySQL%22)%5D%0A%20%20%20%20HOUR%20--%3E%7C%22aggregate%20job%3A%20rows%20older%20than%2048h%22%7C%20DAY%5B(%22bandwidth_usage_daily%3Cbr%2F%3EMySQL%22)%5D%0A%20%20%20%20HOUR%20--%3E%20CHARTS%5B%22Dashboard%20fleet%20chart%3Cbr%2F%3Etop%20consumers%20%C2%B7%20reports%3Cbr%2F%3Etotal-today%20card%22%5D%0A%20%20%20%20DAY%20--%3E%20CHARTS%0A%20%20%20%20DAY%20--%3E%20PRED%5B%22Predictions%3Cbr%2F%3Elinear%20projection%20%2B%207-day%20average%22%5D%0A%20%20%20%20HOUR%20--%3E%20PRED%0A%20%20%20%20HOUR%20--%3E%7C%22prune%20job%20(%3E%2090%20days)%22%7C%20GONE1%5B%22deleted%22%5D%0A%20%20%20%20DAY%20--%3E%7C%22prune%20job%20(%3E%20730%20days)%22%7C%20GONE2%5B%22deleted%22%5D%0A"})]),fallback:o(()=>[...e[2]||(e[2]=[d(" Loading... ",-1)])]),_:1})),e[9]||(e[9]=c('<p>Key properties of the pipeline:</p><ul><li><strong>Node side (5s cycle).</strong> Each poll reads the veth counters, computes per-direction deltas and byte/sec rates, accumulates them into the persisted day/week/month quota counters, and appends the delta to the current hourly bucket in SQLite — including zero-delta buckets, so history shows zeros instead of gaps.</li><li><strong>Panel side (1m cycle).</strong> The poll job reads cumulative <code>rx_bytes_total</code> / <code>tx_bytes_total</code> per server and stores the <em>delta since the last poll</em> in <code>bandwidth_usage_hourly</code>. The last-seen counters are persisted in <code>bandwidth_server_state</code>, so deltas survive queue-worker restarts and cache flushes. A server seen for the first time only stores its baseline — booking its lifetime counters into one hour would fabricate usage. Counter resets (container restarts) fall back to the raw value.</li><li><strong>Peak rates</strong> are kept per bucket (<code>GREATEST</code> on upsert), so the reports page can show the fastest a server ever ran.</li></ul><h3 id="the-48-hour-aggregation-boundary" tabindex="-1">The 48-hour aggregation boundary <a class="header-anchor" href="#the-48-hour-aggregation-boundary" aria-label="Permalink to &quot;The 48-hour aggregation boundary&quot;">​</a></h3><p>Hourly rows older than <strong>48 hours</strong> (<code>aggregate_after_hours</code> in <code>config/bandwidthmonitor.php</code>) are rolled into daily rows by the aggregate job: each hourly row&#39;s bytes are added to its calendar-day row (in the configured timezone), peaks are max-merged, and the hourly row is deleted — all in a transaction per row, so a crash can never double-count. The job processes 1000-row chunks with a 240-second runtime budget per run.</p><p>Every query stitches the two tables at the same moving boundary (<code>now - 48h</code>, truncated to the hour): daily rows cover <code>period_start &lt; boundary</code>, hourly rows cover <code>period_start &gt;= boundary</code>. Since each hour lives in exactly one table, ranges that cross the boundary never double-count and never show gaps.</p><hr><h2 id="components" tabindex="-1">Components <a class="header-anchor" href="#components" aria-label="Permalink to &quot;Components&quot;">​</a></h2><h3 id="node-agent-go-node-module" tabindex="-1">Node agent (Go, <code>node-module/</code>) <a class="header-anchor" href="#node-agent-go-node-module" aria-label="Permalink to &quot;Node agent (Go, `node-module/`)&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Package</th><th>Role</th></tr></thead><tbody><tr><td><code>daemon</code></td><td>Orchestrates everything: boot restore, discovery merge, the 5s enforcement cycle, panel sync loops, the API backend, and the CLI Unix socket</td></tr><tr><td><code>docker</code> (discovery)</td><td>Maps containers to servers. Wings names each game-server container with the server UUID; non-UUID containers are ignored. Resolves each container&#39;s host-side veth via peer ifindex matching (<code>eth0</code> <code>iflink</code> → host <code>ifindex</code>) — never by guessing, since a wrong mapping would shape and count the wrong server&#39;s traffic</td></tr><tr><td><code>monitor</code></td><td>Reads <code>/sys/class/net/&lt;veth&gt;/statistics/{rx,tx}_bytes</code>, computes deltas and bytes/sec rates. A counter reset (container restart, veth recreation) yields a zero delta for that poll</td></tr><tr><td><code>tc</code></td><td>Shells out to <code>tc</code> to build/remove HTB + ingress rules per veth. See <a href="./enforcement">Enforcement</a></td></tr><tr><td><code>quota</code></td><td>Calendar period math (day/week/month boundaries in the effective timezone), rollover of persisted counters, and the exceeded-combo evaluation</td></tr><tr><td><code>panel</code></td><td>HTTP client for the node-facing panel API (register, heartbeat, limits, events, suspend)</td></tr><tr><td><code>api</code></td><td>The panel-facing REST API on <code>:8480</code> — bearer auth with constant-time compare, contract envelope</td></tr><tr><td><code>database</code></td><td>SQLite persistence (WAL mode): servers, counters, hourly history, event queue, key/value config</td></tr><tr><td><code>scheduler</code></td><td>Periodic jobs on a 30s tick: event flush, suspend retry (1m), cleanup (1h), health check (5m)</td></tr><tr><td><code>cleanup</code></td><td>Forgets servers unseen for 72h (configurable), prunes local history beyond retention, compacts the DB</td></tr><tr><td><code>health</code></td><td>Internal diagnostics behind the <code>doctor</code> CLI command</td></tr><tr><td><code>cli</code> / <code>cmd</code></td><td><code>bandwidth-node</code> CLI (status, list, limits, unthrottle, reapply, doctor, service controls) talking to the daemon over the Unix socket; <code>bandwidth-noded</code> is the daemon binary</td></tr></tbody></table><p>Two binaries are installed: <code>bandwidth-noded</code> (the systemd service) and <code>bandwidth-node</code> (the CLI, which speaks JSON to <code>/var/run/bandwidth-node.sock</code>).</p><h3 id="panel-addon-php-laravel-panel-addon" tabindex="-1">Panel addon (PHP/Laravel, <code>panel-addon/</code>) <a class="header-anchor" href="#panel-addon-php-laravel-panel-addon" aria-label="Permalink to &quot;Panel addon (PHP/Laravel, `panel-addon/`)&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Piece</th><th>Role</th></tr></thead><tbody><tr><td><strong>Models</strong></td><td><code>BandwidthNodeToken</code>, <code>BandwidthServerLimit</code>, <code>BandwidthSetting</code>, <code>BandwidthUsageHourly</code>, <code>BandwidthUsageDaily</code>, <code>BandwidthEvent</code> — Eloquent wrappers over the <code>bandwidth_*</code> tables</td></tr><tr><td><strong>Services</strong></td><td><code>BandwidthLimitsService</code> (effective limits, contract payload, pushes), <code>BandwidthNodeTokenService</code> (token generate/verify/view/reset), <code>BandwidthSettingsService</code> (key/value settings, atomic <code>config_version</code> bumps), <code>BandwidthUsageQueryService</code> (stitched hourly/daily queries), <code>BandwidthPredictionService</code> (linear + 7-day-average projections), <code>BandwidthNodeHttpClient</code> (panel→node calls with retry on 502/503/504 and a per-node circuit breaker: opens after 5 failures in 60s, half-opens after 30s)</td></tr><tr><td><strong>Jobs</strong></td><td><code>BandwidthPollJob</code> (minute stats pull → hourly rollups), <code>BandwidthAggregateJob</code> (48h rollup), <code>BandwidthPruneJob</code> (retention), <code>BandwidthPushLimitsJob</code> (limits push to one node)</td></tr><tr><td><strong>Controllers</strong></td><td>Six admin controllers (dashboard, nodes, servers, reports, settings, events) plus the node-facing <code>BandwidthNodeApiController</code> behind token-auth middleware</td></tr><tr><td><strong>Listeners</strong></td><td><code>HandleServerCreated</code> / <code>HandleServerUpdated</code> — prefill the bandwidth fields on the server build configuration so new servers get the defaults from day one</td></tr><tr><td><strong>Console commands</strong></td><td><code>AggregateUsageCommand</code>, <code>PollNodesCommand</code>, <code>PruneUsageCommand</code> — manual/scheduled wrappers around the jobs</td></tr></tbody></table><hr><h2 id="database-schemas" tabindex="-1">Database schemas <a class="header-anchor" href="#database-schemas" aria-label="Permalink to &quot;Database schemas&quot;">​</a></h2><h3 id="node-side-—-sqlite-var-lib-bandwidth-node-bandwidth-node-db-wal-mode" tabindex="-1">Node side — SQLite (<code>/var/lib/bandwidth-node/bandwidth-node.db</code>, WAL mode) <a class="header-anchor" href="#node-side-—-sqlite-var-lib-bandwidth-node-bandwidth-node-db-wal-mode" aria-label="Permalink to &quot;Node side — SQLite (`/var/lib/bandwidth-node/bandwidth-node.db`, WAL mode)&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Table</th><th>Purpose</th><th>Notable columns</th></tr></thead><tbody><tr><td><code>servers</code></td><td>One row per known server: identity, live counters, per-period quota usage, enforcement state</td><td><code>uuid</code> (PK), <code>container_id</code>, <code>veth_iface</code>, <code>state</code>, <code>limits_json</code>, <code>first_seen</code>/<code>last_seen</code>, <code>rx/tx_bytes_total</code>, <code>rx/tx_rate_bps</code>, <code>rx/tx_used_{day,week,month}</code>, <code>throttled</code>, <code>exceeded_json</code>, <code>suspended</code>, <code>overrides_json</code></td></tr><tr><td><code>usage_hourly</code></td><td>Local hourly history for the history API</td><td><code>(uuid, bucket_start)</code> PK, <code>rx_bytes</code>, <code>tx_bytes</code></td></tr><tr><td><code>events_queue</code></td><td>Outbound panel events awaiting delivery</td><td><code>id</code>, <code>payload</code> (JSON), <code>attempts</code>, <code>created_at</code></td></tr><tr><td><code>config</code></td><td>Key/value agent state</td><td><code>key</code> (PK) — stores <code>config_version</code> and the persisted <code>period_start_{day,week,month}</code> boundaries</td></tr><tr><td><code>schema_version</code></td><td>Migration marker</td><td><code>version</code></td></tr></tbody></table><p>Unparseable (&quot;poison&quot;) event payloads are dropped on read so a single bad row can never block the queue.</p><h3 id="panel-side-—-mysql-eight-bandwidth-tables" tabindex="-1">Panel side — MySQL (eight <code>bandwidth_*</code> tables) <a class="header-anchor" href="#panel-side-—-mysql-eight-bandwidth-tables" aria-label="Permalink to &quot;Panel side — MySQL (eight `bandwidth_*` tables)&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Table</th><th>Purpose</th><th>Notable columns</th></tr></thead><tbody><tr><td><code>bandwidth_node_tokens</code></td><td>Pairing + node reachability</td><td><code>node_id</code> (unique), <code>token_hash</code> (bcrypt), <code>token_encrypted</code>, <code>token_prefix</code> (16 hex, indexed), <code>api_url</code>, <code>version</code>, <code>is_online</code>, <code>last_seen_at</code>, <code>health_fail_count</code>, <code>cached_stats</code> (JSON)</td></tr><tr><td><code>bandwidth_server_limits</code></td><td>Per-server override rows (absent = use defaults)</td><td><code>server_id</code> (unique), <code>enabled</code>, <code>rx/tx_speed_mbps</code>, six <code>*_quota_*_gb</code>, <code>exceed_action</code>, <code>throttle_rx/tx_mbps</code></td></tr><tr><td><code>bandwidth_settings</code></td><td>Key/value settings</td><td><code>key</code> (unique), <code>value</code> — includes defaults, timezone, poll interval, retention, and the monotonic <code>config_version</code></td></tr><tr><td><code>bandwidth_usage_hourly</code></td><td>Hourly rollups</td><td><code>(server_id, period_start)</code> unique, <code>rx/tx_bytes</code>, <code>rx/tx_rate_peak_bps</code></td></tr><tr><td><code>bandwidth_usage_daily</code></td><td>Daily rollups (from the 48h aggregation)</td><td>same shape as hourly</td></tr><tr><td><code>bandwidth_events</code></td><td>Enforcement audit log</td><td><code>server_id</code>, <code>node_id</code> (nullable), <code>type</code>, <code>period</code>, <code>direction</code>, <code>message</code>, <code>created_at</code></td></tr><tr><td><code>bandwidth_server_state</code></td><td>Last-seen cumulative counters per server</td><td><code>server_id</code> (unique), <code>last_rx_total</code>, <code>last_tx_total</code>, <code>last_polled_at</code></td></tr><tr><td><code>bandwidth_quota_suspensions</code></td><td>Marker for addon-initiated quota suspensions (gates the name-tag feature)</td><td><code>server_id</code> (unique), <code>original_name</code>, <code>original_description</code>, <code>created_at</code></td></tr></tbody></table><p>All usage/events tables cascade (or null) on server/node deletion, so deleting a Pterodactyl server cleans up its rows.</p><hr><h2 id="server-lifecycle-deletion-transfer" tabindex="-1">Server lifecycle: deletion &amp; transfer <a class="header-anchor" href="#server-lifecycle-deletion-transfer" aria-label="Permalink to &quot;Server lifecycle: deletion &amp; transfer&quot;">​</a></h2><p><strong>Server deleted.</strong> Limits, poll baselines, and usage history (<code>bandwidth_server_limits</code>, <code>bandwidth_server_state</code>, <code>bandwidth_usage_hourly/daily</code>) cascade-delete with the server — no orphans. <code>bandwidth_events</code> keeps its rows with <code>server_id = NULL</code> as an audit trail. On the node, the next discovery scan (~10 s) marks the container stopped and strips its <code>tc</code> rules; the record is purged after 72 h by the cleanup job. The panel poll job silently skips stats for UUIDs it no longer knows.</p><p><strong>Server transferred to another node.</strong> Limits and usage history follow the server (keyed by <code>server_id</code>, unchanged). The <code>Server\\Updated</code> listener detects the <code>node_id</code> change, bumps <code>config_version</code>, and pushes the fresh payload to <strong>both</strong> nodes: the new node&#39;s agent applies the server&#39;s caps on its next pull, and the old node&#39;s full-replace payload drops the server and removes its <code>tc</code> rules.</p><h2 id="concurrency-locking-model-node-agent" tabindex="-1">Concurrency &amp; locking model (node agent) <a class="header-anchor" href="#concurrency-locking-model-node-agent" aria-label="Permalink to &quot;Concurrency &amp; locking model (node agent)&quot;">​</a></h2><p>The agent is a single multi-goroutine process; shared state is coordinated, not shared-nothing:</p><ul><li><strong>Server map</strong> — one <code>sync.RWMutex</code> on the daemon guards the in-memory server map and every server&#39;s mutable fields. Blocking sysfs reads happen on a detached copy <em>outside</em> the lock; results are merged back under it.</li><li><strong>SQLite</strong> — a single connection (<code>max_open_conns: 1</code>) with its own RWMutex around every operation, plus WAL mode, <code>synchronous=NORMAL</code>, and a 5s busy timeout. Single-writer by construction.</li><li><strong>tc manager</strong> — one mutex serializes all <code>tc</code> invocations, so rules can never be half-applied by racing goroutines.</li><li><strong>Monitor</strong> — its own mutex protects the previous-reading snapshots.</li><li><strong>Background goroutines</strong> — registration, heartbeat, Docker event watch, suspend callbacks, and the Unix-socket listener are tracked in a <code>WaitGroup</code>. Shutdown signals them first, closes the socket listener, stops the scheduler and API, drains the WaitGroup, and only then removes tc rules and closes the database and logger — nothing touches closed state.</li><li><strong>Suspend callbacks</strong> are deduplicated (one in flight per server) and retried: 5 attempts with exponential backoff immediately, then a scheduler job every minute until the panel confirms. The agent never permanently gives up on a suspend.</li></ul><hr><h2 id="direction-mapping-read-this-before-trusting-any-chart" tabindex="-1">Direction mapping (read this before trusting any chart) <a class="header-anchor" href="#direction-mapping-read-this-before-trusting-any-chart" aria-label="Permalink to &quot;Direction mapping (read this before trusting any chart)&quot;">​</a></h2><p>Counters are always presented <strong>from the server&#39;s perspective</strong>: RX = inbound to the server, TX = outbound from it. The host-side veth sees the mirror image — the kernel counts veth <code>rx_bytes</code> for traffic the container <strong>sent</strong> (server TX) and veth <code>tx_bytes</code> for traffic delivered <strong>to</strong> the container (server RX). The monitor swaps the two at collection time, which also matches enforcement: an RX cap is policed on ingress into the veth, a TX cap is shaped on egress from it.</p><p>Every number in the panel — stat cards, charts, quotas, reports — uses this server-perspective mapping consistently.</p><hr><h2 id="next-steps" tabindex="-1">Next steps <a class="header-anchor" href="#next-steps" aria-label="Permalink to &quot;Next steps&quot;">​</a></h2><ul><li><strong><a href="./enforcement">Enforcement →</a></strong> — the <code>tc</code> rule anatomy and the quota engine state machine.</li><li><strong><a href="./../user-guide/api">API Reference →</a></strong> — the wire protocol between the halves.</li><li><strong><a href="./../user-guide/admin-panel">Admin Panel Guide →</a></strong> — what the panel does with all this data.</li></ul>',34))])}const A=l(p,[["render",b]]);export{_ as __pageData,A as default};
